SELECT Cancer, COUNT(*) AS n, COUNT(DISTINCT Gene) AS genes,
  SUM(CASE WHEN TRY_CAST("logFC" AS DOUBLE) IS NULL OR TRY_CAST("p-value adjusted" AS DOUBLE) IS NULL THEN 1 ELSE 0 END) AS nonfinite
FROM cancer_cptac WHERE Cancer IN ('Colon AC','Lung AC','Ovary SC') GROUP BY Cancer;

SELECT "Gene", "Disease involvement", "Protein class" FROM proteinatlas
WHERE "Ensembl" IN ('ENSG00000143546','ENSG00000163220','ENSG00000013588','ENSG00000166426','ENSG00000108821','ENSG00000101425','ENSG00000164692','ENSG00000163221','ENSG00000143320','ENSG00000169715','ENSG00000146143','ENSG00000138772')
ORDER BY "Ensembl";
